                let Ok(uuid) = env::var("XRAY_UUID") else {
                    continue;
                };
                let Ok(privkey) = env::var("XRAY_PRIVATE_KEY") else {
                    continue;
                };
                let Ok(short) = env::var("XRAY_SHORT_ID") else {
                    continue;
